"""Optional first editing pass, isolated from the normal project workflow."""
PANEL=r'''
<section class="panel" id="cutPassPanel"><details id="cutPassFold"><summary><b>✂ CUT · Primo montaggio opzionale</b><span class="muted"> Ripartenze, take e pause</span></summary>
<p class="muted">Propone i tagli sul video originale. Puoi ascoltare ogni take, cambiare la scelta e vedere il montaggio prima di confermarlo.</p>
<div class="row"><button id="cutAnalyze" type="button">ANALIZZA CUT</button><button id="cutPreview" type="button" disabled>ANTEPRIMA PULITA</button><button id="cutConfirm" class="primary" type="button" disabled>CONFERMA CUT E CONTINUA</button></div>
<div id="cutProgress" role="status"><progress max="4" value="0"></progress><span></span></div>
<p id="cutSummary"></p><div class="row"><label>Pausa lunga (secondi) <input id="cutPause" type="number" min="0.5" max="5" step="0.1" value="1.2"></label><label>Respiro ai tagli <input id="cutBreath" type="number" min="0.05" max="0.5" step="0.01" value="0.18"></label><button id="cutSavePause" disabled>AGGIORNA PAUSE</button></div>
<div id="cutGroups"></div><details><summary>Testo dopo CUT</summary><p id="cutText"></p></details>
<video id="cutPlayer" controls hidden></video><details><summary>Diagnostica CUT</summary><button id="cutDebugCopy">COPIA DEBUG</button><pre id="cutDebug"></pre></details>
</details></section>
'''
CSS=r'''<style>
#cutPassPanel summary{cursor:pointer;padding:8px 0}#cutPassPanel summary span{margin-left:12px;font-size:12px}#cutProgress{display:flex;gap:12px;align-items:center;margin:14px 0;font-size:12px}#cutProgress progress{width:180px;height:7px;accent-color:var(--lime)}#cutGroups{display:grid;gap:10px;margin:12px 0}.cutGroup{padding:12px;border:1px solid var(--line);border-radius:10px;background:var(--p2)}.cutGroup header{display:flex;justify-content:space-between;gap:12px}.cutTake{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:10px;padding:8px;border-radius:8px;align-items:center;margin-top:5px}.cutTake:has(input:checked){background:#7361a633;outline:1px solid #a995d8}.cutTake small{display:block}#cutPlayer{width:min(100%,420px);max-height:420px;background:#10131d;object-fit:contain;margin:12px 0}#cutDebug{max-height:220px;overflow:auto;white-space:pre-wrap;font-size:11px}#cutPassPanel input[type=number]{width:75px;padding:5px;background:var(--p2);color:var(--ink);border:1px solid var(--line);border-radius:6px}
</style>'''
JS=r'''
let cutPid=null,cutData=null,cutBusy=false,cutListenEnd=null,cutPollBusy=false;
const cutPlayer=$('cutPlayer');cutPlayer.ontimeupdate=()=>{if(cutListenEnd!=null&&cutPlayer.currentTime>=cutListenEnd){cutPlayer.pause();cutListenEnd=null}};
function drawCut(){const plan=cutData?.plan,job=cutData?.job||{},busy=job.status==='running'||cutBusy;for(const id of ['cutAnalyze','cutPreview','cutConfirm','cutSavePause'])$(id).disabled=busy||!!state.run||!state.project?.source_video|| (id!=='cutAnalyze'&&!plan);$('cutProgress').querySelector('progress').value=Number(job.completed||0);$('cutProgress').querySelector('span').textContent=job.message||'Facoltativo · pronto per analizzare';$('cutDebug').textContent=JSON.stringify({project_id:cutPid,job,plan},null,2);if(!plan){$('cutSummary').textContent='';$('cutGroups').innerHTML='';$('cutText').textContent='';return}const rate=Number(plan.fps.split('/')[0])/Number(plan.fps.split('/')[1]||1);$('cutSummary').textContent=`${(plan.source_duration_frames/rate).toFixed(1)} s → ${plan.duration_seconds.toFixed(1)} s · ${plan.groups.length} gruppi di take · ${plan.alternatives.length} alternative conservate · ${plan.segments.length} parti mantenute`;$('cutPause').value=plan.pause_threshold;$('cutBreath').value=plan.breathing;$('cutText').textContent=cutData.text||'';$('cutGroups').innerHTML=plan.groups.map((g,i)=>`<article class="cutGroup"><header><b>${i+1} · ${esc(g.reason)}</b><small>${g.confidence<.85?'Da verificare':Math.round(g.confidence*100)+'%'} · ${g.selected_take>=0?'alternativa salvata':g.selected_take===-2?'gruppo scartato':'da revisionare'}</small></header>${g.texts.map((text,t)=>`<label class="cutTake"><input type="radio" name="cut-${i}" data-group="${i}" value="${t}" ${g.selected_take===t?'checked':''} ${busy?'disabled':''}><span>${esc(text)}<small>Take ${t+1} · ${g.source_ranges?.[t]?.start?.toFixed(1)||'?'}–${g.source_ranges?.[t]?.end?.toFixed(1)||'?'} s${t===g.takes.length-1?' · ultima':''}</small></span><button type="button" data-listen="${i}:${t}">ASCOLTA</button></label>`).join('')}<label class="cutTake"><input type="radio" name="cut-${i}" data-group="${i}" value="-1" ${g.selected_take===-1?'checked':''} ${busy?'disabled':''}><span>Conserva tutte le take</span></label><label class="cutTake"><input type="radio" name="cut-${i}" data-group="${i}" value="-2" ${g.selected_take===-2?'checked':''} ${busy?'disabled':''}><span>Scarta questo gruppo di tentativi</span></label></article>`).join('');$('cutGroups').querySelectorAll('[data-group]').forEach(input=>input.onchange=()=>saveCut({[input.dataset.group]:Number(input.value)}));$('cutGroups').querySelectorAll('[data-listen]').forEach(button=>button.onclick=async()=>{try{const pid=cutPid,[i,t]=button.dataset.listen.split(':').map(Number),r=await api(`/projects/${pid}/cut/words`);if(pid!==state.pid)return;const [a,b]=plan.groups[i].takes[t];cutListenEnd=r.words[b].end;cutPlayer.hidden=false;cutPlayer.src=`/api/curation/projects/${pid}/media/source-video/source`;cutPlayer.onloadedmetadata=()=>{cutPlayer.currentTime=r.words[a].start;cutPlayer.play().catch(reportError)}}catch(e){reportError(e)}})}
async function refreshCut(){if(!state.pid||cutPollBusy)return;cutPollBusy=true;const pid=state.pid;try{const data=await api(`/projects/${pid}/cut`);if(pid!==state.pid)return;const changed=cutPid!==pid||cutData?.plan?.revision!==data.plan?.revision||cutData?.job?.status!==data.job?.status||cutData?.job?.completed!==data.job?.completed||cutData?.job?.message!==data.job?.message;cutPid=pid;cutData=data;if(changed){drawCut();if(data.job?.status==='succeeded'&&data.job?.result?.url&&data.job?.kind==='preview'){cutListenEnd=null;cutPlayer.hidden=false;cutPlayer.src=data.job.result.url}if(data.job?.status==='succeeded'&&data.job?.result?.project_id&&data.job?.kind==='confirm'){const next=data.job.result.project_id,p=await api(`/projects/${next}`);show(p,p.name,`/api/curation/projects/${next}/media/source-video/source`);if(typeof openOnlyWorkflowStepV42==='function')openOnlyWorkflowStepV42(2)}}}catch(e){if(pid===state.pid){$('cutProgress').querySelector('span').textContent=e.message}}finally{cutPollBusy=false}}
async function cutAction(action){if(!state.pid||cutBusy)return;const pid=state.pid;cutBusy=true;drawCut();try{const options={method:'POST'};if(action==='confirm'){options.headers={'Content-Type':'application/json'};options.body=JSON.stringify({revision:cutData.plan.revision})}await api(`/projects/${pid}/cut/${action}`,options)}catch(e){$('cutProgress').querySelector('span').textContent=e.message;reportError(e)}finally{cutBusy=false;await refreshCut();drawCut()}}
async function saveCut(selected={},keepDisc={}){if(cutBusy||!cutData?.plan)return;cutBusy=true;const pid=cutPid;try{const value=await api(`/projects/${pid}/cut`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:cutData.plan.revision,selected_takes:selected,keep_discards:keepDisc,pause_threshold:Number($('cutPause').value),breathing:Number($('cutBreath').value)})});if(pid===state.pid){cutData={...cutData,...value};cutPlayer.pause();cutPlayer.hidden=true;cutPlayer.removeAttribute('src')}}catch(e){reportError(e)}finally{cutBusy=false;drawCut()}}
const cutGroupDraw=drawCut;drawCut=function(){cutGroupDraw();const busy=cutData?.job?.status==='running'||cutBusy;if(busy)$('analyze').disabled=true;const rows=cutData?.plan?.discards||[];if(!rows.length)return;const box=document.createElement('div');box.className='cutGroup';box.innerHTML='<b>Passaggi fuori scena e tentativi abbandonati</b>'+rows.map((d,i)=>`<label class="cutTake"><input type="checkbox" data-discard="${i}" ${d.keep?'checked':''} ${busy?'disabled':''}><span>${esc(d.text)}<small>${esc(d.reason)} · ${d.confidence<.85?'Da verificare':Math.round(d.confidence*100)+'%'} · spunta per conservare</small></span></label>`).join('');$('cutGroups').append(box);box.querySelectorAll('[data-discard]').forEach(input=>input.onchange=()=>saveCut({},{[input.dataset.discard]:input.checked}))};
$('cutAnalyze').onclick=()=>cutAction('analyze');$('cutPreview').onclick=()=>cutAction('preview');$('cutConfirm').onclick=()=>cutAction('confirm');$('cutSavePause').onclick=()=>saveCut();$('cutDebugCopy').onclick=()=>navigator.clipboard.writeText($('cutDebug').textContent).catch(reportError);
const cutDrawBase=draw;draw=function(){cutDrawBase();if(cutPid!==state.pid){cutData=null;cutPid=state.pid;cutPlayer.pause();cutPlayer.hidden=true;cutPlayer.removeAttribute('src');drawCut();refreshCut()}else drawCut()};setInterval(refreshCut,1200);
'''
